def configurar_portafolio_basora_y_actualizar_facturas(apps, schema_editor):
    Portafolio = apps.get_model('gestion_propiedades', 'Portafolio')
    Factura = apps.get_model('gestion_propiedades', 'Factura')

    # 1. Localizar el portafolio de Basora & Arriaga
    portafolios = Portafolio.objects.filter(
        Q(propietario__username__iexact='lbasora@basoraarriaga.com') |
        Q(propietario__email__iexact='lbasora@basoraarriaga.com') |
        Q(nombre__icontains='Basora')
    )

    portafolios.update(formato_concepto_factura='RANGO_FECHAS')

    # 2. Localizar y actualizar las facturas existentes de ese portafolio
    facturas = Factura.objects.filter(
        contrato__propiedad__portafolio__in=portafolios
    ).exclude(concepto__icontains='migrado')

    meses_dict = {
        'enero': 1, 'febrero': 2, 'marzo': 3, 'abril': 4, 'mayo': 5, 'junio': 6,
        'julio': 7, 'agosto': 8, 'septiembre': 9, 'octubre': 10, 'noviembre': 11, 'diciembre': 12,
        'january': 1, 'february': 2, 'march': 3, 'april': 4, 'may': 5, 'june': 6,
        'july': 7, 'august': 8, 'september': 9, 'october': 10, 'november': 11, 'december': 12
    }
    nombres_meses = {
        1: 'ENERO', 2: 'FEBRERO', 3: 'MARZO', 4: 'ABRIL', 5: 'MAYO', 6: 'JUNIO',
        7: 'JULIO', 8: 'AGOSTO', 9: 'SEPTIEMBRE', 10: 'OCTUBRE', 11: 'NOVIEMBRE', 12: 'DICIEMBRE'
    }

    actualizadas = 0
    for f in facturas:
        mes = None
        anio = None

        if f.concepto:
            c_lower = f.concepto.lower()
            for m_name, m_num in meses_dict.items():
                if m_name in c_lower:
                    mes = m_num
                    break
            match_anio = re.search(r'\b(202\d|203\d)\b', f.concepto)
            if match_anio:
                anio = int(match_anio.group(1))

        if not mes or not anio:
            ref = f.fecha_vencimiento or f.fecha_emision or date.today()
            mes = ref.month
            anio = ref.year

        dia = getattr(f.contrato, 'dia_de_pago', 1) or 1
        max_d1 = calendar.monthrange(anio, mes)[1]
        dia_inicio = min(dia, max_d1)

        if mes == 12:
            mes_fin = 1
            anio_fin = anio + 1
        else:
            mes_fin = mes + 1
            anio_fin = anio

        max_d2 = calendar.monthrange(anio_fin, mes_fin)[1]
        dia_fin = min(dia, max_d2)

        mes1_str = nombres_meses.get(mes, '')
        mes2_str = nombres_meses.get(mes_fin, '')

        nuevo_concepto = f"PAGO DESDE EL {dia_inicio} DE {mes1_str} DEL {anio} HASTA EL {dia_fin} DE {mes2_str} DEL {anio_fin}"
        if nuevo_concepto != f.concepto:
            f.concepto = nuevo_concepto
            f.save()
            actualizadas += 1

    print(f"\n[Migración 0044] Portafolio Basora actualizado a RANGO_FECHAS. Facturas existentes actualizadas: {actualizadas}")


